const producer = kafka.producer({
  transactionalId: 'orders-0', idempotent: true, maxInFlightRequests: 1,
})
const tx = await producer.transaction()
try {
  await tx.send({ topic: 'orders', messages: [{ value: JSON.stringify(event) }] })
  await tx.commit()
} catch (err) {
  await tx.abort()
  throw err
}

